class _Numbers:
    def __init__(self):
        self.reads = 0

    def __iter__(self):
        return self

    def __next__(self):
        self.reads += 1
        if self.reads > 50:
            raise AssertionError('running_total read far more numbers than it was asked for')
        return self.reads

src = _Numbers()
totals = running_total(src)
assert next(totals) == 1
assert src.reads == 1, f'after the first total it had read {src.reads} numbers; read one number per total'
assert next(totals) == 3 and next(totals) == 6
assert src.reads == 3, f'after three totals it had read {src.reads} numbers; read one number per total'

import itertools
def _endless():
    n = 0
    while True:
        n += 1
        if n > 1000:
            raise AssertionError('running_total tried to read the whole endless stream before giving a total')
        yield n

assert list(itertools.islice(running_total(_endless()), 4)) == [1, 3, 6, 10]

